Certainly! Debouncing is a common technique used to optimize performance by limiting the frequency at which a function is executed. Instead of running a function immediately every time an event is triggered, it runs the function only after that event has stopped occurring for a certain period of time.

Here's a JavaScript function that implements debouncing:

```javascript
function debounce(func, wait) {
    let timeoutId;

    return function (...args) {
        // Clear the previous timeout if it exists
        if (timeoutId) {
            clearTimeout(timeoutId);
        }

        // Set a new timeout with the specified wait time
        timeoutId = setTimeout(() => {
            func.apply(this, args);
        }, wait);
    };
}

// Example usage:
